        questions = B.spread(listOf(
            // Identity, governance and monitoring: logging and monitoring
            B.q("sa-m3-1", "sa-monitoring", "Two tables in the Log Analytics workspace must also be copied, as data arrives, to a storage account for a data science team, with no code to maintain. What do you recommend?", listOf("A scheduled query that runs every hour and writes to storage", "A data export rule on the workspace for those tables", "A second diagnostic setting on every resource", "Manual exports from the portal each week"), setOf(1), "A Log Analytics data export rule continuously copies chosen tables to a storage account or an event hub as data is ingested. It is configured once on the workspace, with no code.",
                scenario = "Pennyroyal Bank collects sign-in and app logs for its Android banking app in one workspace. The data science team wants two of those tables as files in storage to train a fraud model.",
                whyWrong = mapOf(
