            ),
            B.q("sa-m3-3", "sa-monitoring", "The AKS clusters' Prometheus metrics must be collected without running Prometheus servers, and shown in Grafana dashboards the team already knows. What do you recommend? Select two.", listOf("Azure Monitor managed service for Prometheus", "Azure Managed Grafana", "A self-hosted Prometheus server on each cluster", "Azure Advisor"), setOf(0, 1), "Azure Monitor managed service for Prometheus collects and stores Prometheus metrics without servers to run. Azure Managed Grafana is a managed Grafana that connects to it, so the team keeps its familiar dashboards.",
                scenario = "Quickfern's Android delivery app runs on three AKS clusters. Its engineers use Prometheus and Grafana from a previous job but do not want to patch and scale the servers themselves.",
                whyWrong = mapOf(
                    2 to "A self-hosted Prometheus is the server the team wants to avoid running.",
                    3 to "Advisor gives best-practice recommendations. It does not collect or display metrics.",
