            B.q("sa-m3-8", "sa-identity", "Staff must sign in to the company's own Android app with their Entra accounts, and the app must call the company's API on their behalf. What do you recommend?", listOf("Use the resource owner password credentials flow in the app to get tokens with each user's password", "Register the API in Entra ID and give the app a client secret, using the client credentials flow", "Register the app and API in Entra ID, sign users in with MSAL, and have the API validate access tokens", "Put API Management in front of the API and compile a subscription key into the app for each call"), setOf(2), "The app and the API are registered in Microsoft Entra ID. The Microsoft Authentication Library (MSAL) signs the user in on the phone and gets an access token for the API, which checks the token on each call. No passwords or keys live in the app.",
                scenario = "Hollins Engineering is building an Android inspection app for its 600 engineers. It calls an internal API on Azure App Service that must know which engineer is calling.",
                whyWrong = mapOf(
