            B.q("sa-m3-10", "sa-authorization", "The customer-managed key that encrypts a storage account must rotate every 90 days with no outage or manual steps. What do you recommend?", listOf("A key rotation policy in Key Vault, with the storage account using a versionless key URI", "A reminder for an engineer to create a new key and update the account", "A new storage account every 90 days", "Switch to Microsoft-managed keys"), setOf(0), "Key Vault rotation policies create a new key version on a schedule. When the storage account points at the key without a version, it picks up the newest version automatically, so rotation causes no outage.",
                scenario = "Cardew Health stores scans from its Android clinic app with a customer-managed key, as the regulator requires. The auditors now also require rotation every 90 days, without downtime.",
                whyWrong = mapOf(
