            B.q("sa-m3-11", "sa-authorization", "Scripts on on-premises servers must read secrets from Key Vault without any credential stored on the servers. What do you recommend?", listOf("Register an app in Entra ID and keep its client secret in a protected file on each server", "Onboard the servers to Azure Arc and give their managed identities the Key Vault Secrets User role", "Register an app in Entra ID and install its certificate in each server's local certificate store", "Give each server a user-assigned managed identity with the Key Vault Secrets User role, without Arc"), setOf(1), "Azure Arc-enabled servers get a system-assigned managed identity, just like Azure VMs. Scripts on the server request tokens for that identity, which you grant access to Key Vault, so no secret is stored on the server.",
                scenario = "Dunmore Foods still runs nightly scripts on servers in its factory that update the product catalogue used by its Android ordering app. The scripts need a database password kept in Key Vault.",
                whyWrong = mapOf(
