            // Governance
            B.q("sa-m3-13", "sa-governance", "Finance needs costs grouped by the CostCentre tag that is set on subscriptions and resource groups, without changing tags on resources. What do you recommend?", listOf("Turn on tag inheritance in Microsoft Cost Management", "Assign a modify policy that copies tags to all resources", "Tag every resource by hand", "Create a budget for each resource group"), setOf(0), "Cost Management's tag inheritance applies subscription and resource group tags to the cost records of child resources. Reports group costs by those tags, while the resources' own tags stay as they are.",
                scenario = "Elsworth Media's subscriptions and resource groups carry a CostCentre tag, but resources often do not. Teams are not allowed to change resource tags in production, yet finance wants costs for the Android streaming app split by cost centre.",
                whyWrong = mapOf(
