            B.q("sa-m3-16", "sa-governance", "Every quarter, the owners of each production subscription must confirm who still needs the Owner and Contributor roles, and access that is not confirmed must be removed automatically. What do you recommend?", listOf("Access reviews of Azure resource roles in Privileged Identity Management, with auto-apply", "Make Owner and Contributor eligible in PIM, so that every activation needs approval", "An Azure Policy that audits role assignments and lists them on the compliance dashboard", "A Conditional Access policy that blocks sign-in for accounts inactive for 90 days"), setOf(0), "PIM can run access reviews on Azure resource roles. Reviewers confirm or deny each assignment, and with auto-apply the results take effect when the review ends, removing access nobody vouched for.",
                scenario = "Albury Logistics found former contractors still holding Owner on the production subscriptions behind its Android tracking app, a year after they left.",
