            // Data: relational
            B.q("sa-m3-17", "sa-relational", "The audit team must be able to prove that no one, administrators included, has secretly changed past rows in the payments table. What do you recommend?", listOf("Ledger tables in Azure SQL Database, with database digests stored in immutable storage", "Temporal tables, so every earlier version of each row is kept in a history table", "SQL auditing to a storage account, recording every statement run against the table", "Always Encrypted on the payment columns, so administrators cannot read the values"), setOf(0), "The ledger feature keeps a cryptographic record of every change to ledger tables. Digests saved to immutable storage let you verify later that no row was tampered with, even by an administrator.",
                scenario = "Fennick Payments' Android wallet records every transfer in Azure SQL Database. Its regulator wants evidence that the history cannot be quietly edited.",
                whyWrong = mapOf(
