            B.q("sa-m3-18", "sa-relational", "The company has SQL Server licences with Software Assurance and wants to use them to lower the price of a new Azure SQL database. Which purchasing model must you choose?", listOf("The DTU model", "The vCore model", "Either, the discount works in both", "Neither, licences cannot be used in PaaS"), setOf(1), "The vCore model shows compute and licence separately, so the Azure Hybrid Benefit can apply existing SQL Server licences with Software Assurance. The DTU model bundles everything into one price and does not offer it.",
                scenario = "Wilmot Distribution is moving the database behind its Android ordering app to Azure SQL Database. It owns SQL Server Enterprise licences with Software Assurance from its data centre.",
