            B.q("sa-m3-21", "sa-relational", "Only Microsoft Entra identities may connect to Azure SQL, and the app must connect with no password at all. What do you configure? Select two.", listOf("Turn on Microsoft Entra-only authentication for the logical server", "Connect the app with its managed identity, created as a database user", "Create a SQL login with a long password for the app", "Store the connection string with the SA password in Key Vault"), setOf(0, 1), "Microsoft Entra-only authentication disables SQL logins on the server. The app's managed identity is added as a database user and gets tokens from Azure, so no password exists to leak.",
                scenario = "After a leaked SQL password, Corran Fitness wants every connection to the database behind its Android workout app to use Entra identities.",
