                ),
            ),
            B.q("sa-m3-28", "sa-data-integration", "Raw data from many sources must be kept as it arrived, then cleaned, then shaped into business-ready tables, all in Delta Lake, so that any step can be rebuilt. What design do you recommend?", listOf("Load each source straight into business-ready gold tables in Delta Lake", "A medallion architecture in Delta Lake, with separate bronze, silver and gold layers", "A star schema in Delta Lake, with fact and dimension tables loaded from the sources", "Delta Lake time travel on the final tables, with raw files deleted after loading"), setOf(1), "The medallion architecture keeps data in layers. Bronze holds raw data as it came, silver holds cleaned and joined data, and gold holds tables ready for reports. Keeping bronze means you can rebuild later layers after a fix.",
                scenario = "Saltford Telecom's data engineers use Azure Databricks to combine billing, network and Android app usage data. A bug last year corrupted reports, and the raw data had already been thrown away.",
                whyWrong = mapOf(
                    0 to "With no raw layer, a bug in transformation cannot be fixed by reprocessing.",
                    2 to "A star schema is a good shape for the final tables, but it keeps no raw or cleaned layer to rebuild from.",
                    3 to "Time travel keeps older versions of the final tables only until they are vacuumed, and it cannot rerun a fixed transformation without the raw data, which is what was lost last year.",
                ),
            ),
            B.q("sa-m3-29", "sa-data-integration", "Data Factory must copy from a storage account and a SQL database that allow only private endpoints, without running a self-hosted integration runtime VM. What do you recommend?", listOf("An Azure integration runtime in a managed virtual network, with managed private endpoints to the sources", "The default Azure integration runtime, with its outbound IP ranges allowed on the sources' firewalls", "A self-hosted integration runtime on a new VM in the virtual network that holds the private endpoints", "A private endpoint for the data factory itself, so that the factory reaches the sources privately"), setOf(0), "A Data Factory managed virtual network runs the Azure integration runtime in a network Microsoft manages. Managed private endpoints connect it privately to the data stores, so there is no VM to patch.",
                scenario = "Ivybridge Bank locks every data store behind its Android banking app to private endpoints. The data team needs nightly copies into the data lake but does not want to run servers.",
                whyWrong = mapOf(
                    1 to "Allowing IP ranges needs public network access on the sources, which the bank's private-endpoint-only rule forbids.",
                    2 to "A self-hosted runtime works but is the VM the team wants to avoid.",
                    3 to "A private endpoint on the factory carries traffic to Data Factory, from a self-hosted runtime or the portal. It does not connect the Azure runtime to the data stores.",
                ),
            ),
            B.q("sa-m3-30", "sa-data-integration", "A nightly pipeline copies a 2-billion-row orders table in full and takes too long. Only a few thousand rows change each day. What do you recommend?", listOf("Split the full copy into parallel partitions by order ID so that it finishes sooner", "Copy only changed rows, found with a watermark column or change data capture", "Raise the copy activity's data integration units to the maximum for the nightly run", "Copy the full table once a week on Sunday and skip the weekday copies"), setOf(1), "An incremental load copies only rows that changed since the last run. A watermark column, such as a last-modified time, or change data capture, which records inserts, updates and deletes, tells the pipeline which rows to take.",
                scenario = "Hartwell Pharmacy's orders table, written by its Android prescription app, is copied in full every night into the data lake. The copy now runs past 08:00, when reports are due.",
                whyWrong = mapOf(
                    0 to "Parallel partitions can speed up the copy, but it still moves 2 billion rows every night to pick up a few thousand, and the time grows with the table.",
                    2 to "More copy power shortens the run a little but still moves 2 billion rows to get a few thousand.",
                    3 to "Weekly copies make the reports up to a week old.",
                ),
            ),
            // Business continuity: backup and disaster recovery
            B.q("sa-m3-31", "sa-backup-dr", "Managed disks must be backed up several times a day with no agent in the VM and no effect on the running app. What do you recommend?", listOf("Azure Disk Backup to a Backup vault", "The MARS agent", "Copy the VHD files by hand", "Turn on geo-redundant storage for the disks"), setOf(0), "Azure Disk Backup takes incremental snapshots of managed disks on a schedule, several times a day if needed, through a Backup vault. It needs no agent and does not interrupt the VM.",
                scenario = "Owlbridge's video transcoding VMs keep work in progress on data disks. The team behind the Android video app wants restore points every few hours without installing anything in the VMs.",
                whyWrong = mapOf(
                    1 to "MARS is an agent installed in Windows that backs up files, the opposite of the requirement.",
                    2 to "Manual copies are slow, inconsistent and not scheduled.",
                    3 to "Managed disks do not offer GRS, and replication is not backup anyway.",
                ),
            ),
            B.q("sa-m3-32", "sa-backup-dr", "On-premises Hyper-V VMs and a SQL Server must be backed up to Azure with application-consistent backups and fast local restores. What do you recommend?", listOf("The MARS agent installed in each Hyper-V VM, sending copies to a Recovery Services vault", "Microsoft Azure Backup Server on-premises, sending copies to a Recovery Services vault", "Azure Site Recovery replicating the Hyper-V VMs to a Recovery Services vault", "Azure Backup for SQL Server, using the workload backup extension on the SQL Server VM"), setOf(1), "Microsoft Azure Backup Server (MABS) runs on-premises and backs up Hyper-V VMs, SQL Server and other workloads with application awareness. It keeps recent copies on local disks for fast restores and sends longer-term copies to Azure.",
                scenario = "Fernbank Council still runs the database for its Android bin-collection app on Hyper-V in the town hall. It needs consistent SQL backups and quick restores without waiting for downloads.",
                whyWrong = mapOf(
                    0 to "MARS backs up files, folders and system state, not whole VMs or SQL databases consistently, and it keeps no local copy for fast restores.",
                    2 to "Site Recovery replicates for disaster recovery. It does not keep a history of backups or give fast local restores.",
                    3 to "That workload backup is for SQL Server running in Azure VMs, not on on-premises Hyper-V.",
                ),
            ),
            B.q("sa-m3-33", "sa-backup-dr", "A developer accidentally dropped a whole Azure SQL database yesterday. How do you get it back?", listOf("Restore the deleted database from its automated backups, as it was before the drop", "Fail over to a geo-secondary of the database and make it the new primary", "Undo the drop from the activity log entry that recorded the delete operation", "It cannot be recovered, because dropping a database also removes its backups"), setOf(0), "Azure SQL keeps automated backups of a deleted database for its retention period. You can restore it, as it was at the moment of deletion or an earlier point, from the list of deleted databases on the server.",
                scenario = "A cleanup script at Rookwood Games dropped the leaderboard database of its Android game instead of a test copy. Backups use the default seven-day retention, and there is no geo-replica.",
                whyWrong = mapOf(
                    1 to "Failover is for outages. A dropped database is a deliberate change, and here there is no geo-secondary at all.",
                    2 to "The activity log records the deletion but holds no data and has no undo.",
                    3 to "Azure SQL keeps the backups of a deleted database for its retention period, so it can be restored.",
                ),
            ),
            B.q("sa-m3-34", "sa-backup-dr", "VMs in a region with availability zones must recover in another zone of the same region, because data must not leave the region. What do you recommend?", listOf("Azure Site Recovery zone-to-zone disaster recovery", "Cross-region restore from a backup vault", "Azure Site Recovery to the paired region", "Snapshots of the OS disks"), setOf(0), "Site Recovery can replicate VMs from one availability zone to another in the same region, with recovery points and orchestrated failover. The data stays in the region.",
                scenario = "Bergholt Bank must keep data for its Android banking app inside one country, which has a single Azure region with zones. It still needs disaster recovery for its VMs.",
                whyWrong = mapOf(
                    1 to "Cross-region restore copies data to another region, which the rule forbids.",
                    2 to "The paired region is in another country here, so data would leave.",
                    3 to "Snapshots are only restore points. Incremental snapshots are kept on zone-redundant storage (ZRS) where the region offers it, so they can survive a zone outage, but there is no continuous replication, no recovery plan and no orchestrated failover. Each VM would have to be rebuilt by hand, and OS-disk snapshots alone leave out any data disks.",
                ),
            ),
            B.q("sa-m3-35", "sa-backup-dr", "Backups must stay recoverable for weeks even if an attacker deletes them, and the protection itself must be impossible to switch off. What do you configure on the vault?", listOf("Enhanced soft delete set to always-on, with a long soft delete period", "Geo-redundant storage with Cross Region Restore, so a copy lives in a second region", "Azure Monitor alerts on backup deletion, sent to the security team's phones", "A longer retention period in the backup policy, such as a year of daily points"), setOf(0), "Soft delete keeps deleted backup data for a period, 14 days by default and up to 180 days with enhanced soft delete. Set to always-on, soft delete cannot be turned off, so an attacker cannot remove the safety net.",
                scenario = "Malvern Logistics lost backups in a ransomware attack at a partner company and wants a guarantee for the VMs behind its Android tracking app.",
                whyWrong = mapOf(
                    1 to "Geo-redundancy decides where copies live, to survive a regional outage. It does not make a deletion reversible.",
                    2 to "An alert tells you what happened, after the fact, and brings nothing back.",
                    3 to "A longer retention period keeps more restore points, but by itself it does nothing when someone deletes the backup items or shortens the policy. Only soft delete keeps deleted data recoverable.",
                ),
            ),
            B.q("sa-m3-36", "sa-backup-dr", "Hyper-V VMs in a small office without System Center must fail over to Azure if the office is lost, with minutes of data loss. What do you recommend?", listOf("Azure Site Recovery replicating the Hyper-V VMs to Azure", "Hyper-V Replica to a second host in the same office", "Azure Backup Server backing up the VMs to Azure each night", "Azure Migrate replicating the VMs for a one-time move to Azure"), setOf(0), "Site Recovery replicates Hyper-V VMs to Azure continuously, with or without System Center Virtual Machine Manager. If the office is lost, you fail over and the VMs start in Azure with only minutes of data lost.",
                scenario = "Elmbridge Dental's two Hyper-V hosts run its appointment system, which the Android booking app uses. A flood warning made the owners ask for a real disaster recovery plan.",
                whyWrong = mapOf(
                    1 to "Both hosts are in the same office, so losing the office loses the replica too.",
                    2 to "Nightly backups lose up to a day of data and give no failover, so each VM must be rebuilt by a restore.",
                    3 to "Azure Migrate moves servers once. It does not keep a standby copy for disasters.",
                ),
            ),
            // Business continuity: high availability
            B.q("sa-m3-37", "sa-high-availability", "Two VMs behind a load balancer sit in different availability zones. The load balancer must keep working if any one zone fails. What do you choose?", listOf("A Basic Load Balancer", "A Standard Load Balancer with a zone-redundant front end", "A Standard Load Balancer with a zonal front end in zone 1", "DNS round robin"), setOf(1), "A Standard Load Balancer's front end can be zone-redundant, served from every zone at once, so it survives the loss of any one zone and keeps sending traffic to the VMs that remain.",
                scenario = "Hollybrook's chat service for its Android app runs on two VMs in zones 1 and 2. Last year the load balancer itself was the single point of failure in an outage.",
                whyWrong = mapOf(
                    0 to "The Basic Load Balancer has been retired and never supported availability zones.",
                    2 to "A zonal front end lives in one zone and fails with it.",
                    3 to "DNS round robin keeps sending users to a failed VM until caches expire.",
                ),
            ),
            B.q("sa-m3-38", "sa-high-availability", "Users write to the nearest region, and two users sometimes update the same item in different regions at once. How does Cosmos DB with multi-region writes settle such conflicts by default?", listOf("It rejects the second write", "Last writer wins, using a timestamp property", "It keeps both versions forever", "It locks the item globally before each write"), setOf(1), "With multi-region writes, conflicts are settled by a policy. The default is last writer wins, based on the _ts timestamp or a property you choose. A custom policy using a stored procedure is also possible.",
                scenario = "Juniperhill's Android note-taking app writes to whichever Cosmos DB region is closest. A user editing on a phone and a tablet in different countries can update the same note at once.",
                whyWrong = mapOf(
                    0 to "Neither write is rejected; each region accepts writes locally, then conflicts are settled.",
                    2 to "Versions are not kept forever; the policy picks a winner.",
                    3 to "A global lock would remove the low-latency benefit of local writes.",
                ),
            ),
            B.q("sa-m3-39", "sa-high-availability", "A Container Apps environment must keep its apps running if one data centre fails. What must you do? Select two.", listOf("Create the environment in a custom virtual network", "Enable zone redundancy when creating the environment", "Use a single replica for each app", "Add a deployment slot"), setOf(0, 1), "Zone redundancy is chosen when a Container Apps environment is created, and it needs the environment to use your own virtual network. Replicas are then spread across availability zones.",
                scenario = "Pinehurst's API for its Android ride-share app runs in Azure Container Apps. A zone outage last year took it offline, and the team is rebuilding the environment.",
                whyWrong = mapOf(
                    2 to "A single replica sits in one zone, so it fails with that zone.",
                    3 to "Deployment slots are an App Service feature, and they do not add zone resilience.",
                ),
            ),
            B.q("sa-m3-40", "sa-high-availability", "A SQL Managed Instance must survive a data centre failure in its region with no data loss and readable secondary copies. Which configuration fits?", listOf("Business Critical with zone redundancy enabled", "General Purpose with locally redundant backups", "A single instance with daily backups", "An instance pool"), setOf(0), "Business Critical keeps several replicas in an Always On availability group, one of them readable. With zone redundancy those replicas sit in different zones, so a data centre failure causes a fast automatic failover without data loss.",
                scenario = "Torridge Water's billing system behind its Android account app runs on SQL Managed Instance. The regulator requires it to survive a data centre failure with no lost payments.",
                whyWrong = mapOf(
                    1 to "LRS backups and a single compute node do not keep the instance running through a zone failure.",
                    2 to "Restoring from daily backups loses up to a day of data.",
                    3 to "Instance pools share resources between small instances; they do not add zone resilience.",
                ),
            ),
            B.q("sa-m3-41", "sa-high-availability", "The regional web entry point with WAF must survive a data centre failure and scale with demand. What do you deploy?", listOf("Application Gateway v2 with autoscaling, across availability zones", "A single NVA VM running a web firewall", "Application Gateway in one zone with a fixed instance count", "Traffic Manager alone"), setOf(0), "Application Gateway v2 can span availability zones and autoscale, adding instances as traffic grows, so the entry point keeps running through a zone failure.",
                scenario = "Wyvern Ticketing's Android app sends all traffic to one regional entry point with a web application firewall. Big on-sale moments bring ten times the usual traffic.",
                whyWrong = mapOf(
                    1 to "One VM is a single point of failure and cannot scale on its own.",
                    2 to "One zone and a fixed size fail both requirements.",
                    3 to "Traffic Manager is DNS-based routing with no WAF and no regional HTTP entry point.",
                ),
            ),
            // Infrastructure: compute
            B.q("sa-m3-42", "sa-compute", "When a new order email arrives in a shared mailbox, its attachment must be saved to SharePoint and a row added to a CRM, designed visually by the operations team. What do you recommend?", listOf("Azure Logic Apps with built-in connectors", "A Functions app written in C#", "Azure Batch", "A VM running a scheduled script"), setOf(0), "Logic Apps is a serverless workflow service with hundreds of connectors for services such as Outlook, SharePoint and common CRMs. Workflows are designed in a visual designer, which suits teams that do not write code.",
                scenario = "Cloverleaf Supplies receives orders by email as well as through its Android app. The operations team, who do not code, want to automate the email orders.",
                whyWrong = mapOf(
                    1 to "Functions needs developers and code for each service the workflow touches.",
                    2 to "Batch runs large parallel compute jobs, not business workflows.",
                    3 to "A scripted VM is a server to run, and the team cannot maintain code.",
                ),
            ),
            B.q("sa-m3-43", "sa-compute", "A single container must run a one-off data repair task for about 20 minutes, today, with no cluster or app platform to set up. What do you recommend?", listOf("Azure Container Instances", "Azure Kubernetes Service", "Azure Service Fabric", "A new App Service plan"), setOf(0), "Azure Container Instances runs a container in seconds, billed per second, with no servers or cluster to set up. It suits simple, short-lived tasks.",
                scenario = "A bug in Glowberry's Android fitness app wrote bad data overnight. The team has a container image that fixes it and wants it run once, now.",
                whyWrong = mapOf(
                    1 to "Creating a Kubernetes cluster for a 20-minute task is far too much.",
                    2 to "Service Fabric is a platform for microservices you would have to set up first.",
                    3 to "App Service is for long-running web apps, not one-off tasks.",
                ),
            ),
            B.q("sa-m3-44", "sa-compute", "Every VM must start from the same hardened image, rebuilt each month with patches, and available in three regions. What do you recommend? Select two.", listOf("Azure VM Image Builder to build the image each month", "An Azure Compute Gallery that replicates image versions to the three regions", "Take a snapshot of a running production VM", "Use the default Marketplace image and patch after deployment"), setOf(0, 1), "VM Image Builder builds images from a template, applying hardening and patches. It has no built-in timer: its SourceImage trigger starts a new build when the source platform or gallery image gets a new version, and a scheduled pipeline or automation job can start a build each month. Azure Compute Gallery stores versioned images and replicates them to the regions where you deploy.",
                scenario = "Ashgrove Security runs the back end for its Android alarm app on VMs in three regions. Auditors found VMs built from images that had not been patched for a year.",
                whyWrong = mapOf(
                    2 to "Snapshots of a live VM capture its data and drift, and are not a clean, repeatable image.",
                    3 to "Patching after deployment leaves every new VM exposed until it finishes.",
                ),
            ),
            B.q("sa-m3-45", "sa-compute", "Stateless web VMs in a scale set must start and reimage fast, and the OS disk costs nothing extra. What do you recommend?", listOf("Ephemeral OS disks", "Premium SSD OS disks", "Ultra disks", "A data disk for the OS"), setOf(0), "Ephemeral OS disks live on the VM host's local storage, so they are created quickly, cost nothing extra and give fast reads and writes. They are lost when the VM is reimaged or moved, which is fine for stateless VMs.",
                scenario = "Bluebell Media's image API for its Android app runs on a scale set that grows quickly in the evening. New instances take too long to start.",
                whyWrong = mapOf(
                    1 to "Premium SSDs are persistent and billed, which stateless VMs do not need.",
                    2 to "Ultra disks cannot be OS disks, and they are expensive.",
                    3 to "An OS cannot run from a data disk; the OS disk is required.",
                ),
            ),
            B.q("sa-m3-46", "sa-compute", "A tightly coupled engineering simulation needs hundreds of cores talking over a low-latency network, and the team wants to keep its Slurm scheduler. What do you recommend?", listOf("Azure CycleCloud managing a Slurm cluster on HPC VMs with InfiniBand", "Azure Batch pools of HPC VMs with InfiniBand, with the jobs submitted through Batch", "A scale set of general-purpose VMs running the team's Slurm scheduler", "Azure Container Apps jobs running the simulation across many replicas"), setOf(0), "Tightly coupled jobs use MPI, a way for processes on many machines to exchange data constantly, so they need HPC VMs with InfiniBand networking. Azure CycleCloud creates and scales clusters with schedulers such as Slurm, so the team keeps its tools.",
                scenario = "Northwind Aero runs aerodynamics simulations with Slurm on its own cluster, which is full. The results feed an Android app its engineers use on site.",
                whyWrong = mapOf(
                    1 to "Batch can run MPI jobs, but it is its own scheduler, so the team would have to give up Slurm.",
                    2 to "General-purpose VMs have no InfiniBand, so a tightly coupled MPI job would stall on network latency.",
                    3 to "Container Apps jobs run independent containers, with no low-latency HPC networking for MPI.",
                ),
            ),
            // Infrastructure: application architecture
            B.q("sa-m3-47", "sa-app-architecture", "Image-processing tasks must be queued simply and cheaply, the backlog can grow beyond 100 GB, and order and duplicate detection do not matter. What do you recommend?", listOf("Azure Storage queues", "Azure Service Bus Premium with sessions", "Azure Event Hubs", "Azure Event Grid"), setOf(0), "Storage queues are a simple, low-cost queue in a storage account. A queue can hold as much as the account can store, which suits large backlogs when advanced features such as ordering and duplicate detection are not needed.",
                scenario = "Pixelharbor's Android photo app queues a resize task for every upload. During promotions the backlog grows past 100 GB, and the team pays for every queue feature it does not use.",
                whyWrong = mapOf(
                    1 to "Sessions and Premium cost more for ordering the team does not need.",
                    2 to "Event Hubs is for streams of events read by many consumers, not a task queue.",
                    3 to "Event Grid pushes events to handlers and does not hold a large backlog of work.",
                ),
            ),
            B.q("sa-m3-48", "sa-app-architecture", "Event Grid delivers events to a webhook that is sometimes down for hours. No event may be lost. What do you configure?", listOf("A retry policy, plus a dead-letter destination in Blob Storage for undelivered events", "A retry policy set to the maximum of 30 attempts and a 24-hour event time-to-live", "A second event subscription to the same webhook, so that one of the two gets through", "Output batching on the subscription, so that events are held until the webhook comes back"), setOf(0), "Event Grid retries delivery with back-off for up to 24 hours by default. With a dead-letter destination, events that still cannot be delivered are written to a storage container instead of being dropped.",
                scenario = "Tealbrook Insurance's claims system receives events for every photo uploaded from its Android app. Its webhook goes down during weekend maintenance and some events vanished.",
                whyWrong = mapOf(
                    1 to "Those are already the default limits. When either is reached and no dead-letter destination is set, Event Grid drops the event.",
                    2 to "A second subscription to the same endpoint fails the same way, and it sends duplicates when the webhook is up.",
                    3 to "Batching groups events into one delivery for throughput. Event Grid does not delay events to build a batch, and it keeps nothing beyond the normal retry limits.",
                ),
            ),
            B.q("sa-m3-49", "sa-app-architecture", "Teams across the company build hundreds of APIs on different gateways. Architects need one inventory of every API, its versions and owners, with design rules checked. What do you recommend?", listOf("Azure API Center", "A spreadsheet kept by the architects", "One API Management instance for all APIs", "Azure Front Door"), setOf(0), "Azure API Center is an inventory of an organisation's APIs, whatever gateway or platform runs them. It records versions, owners and metadata, and can check API definitions against design rules.",
                scenario = "Greenway Bank has APIs in several API Management instances, in AKS and on-premises, including the ones behind its Android app. Nobody can say how many there are.",
                whyWrong = mapOf(
                    1 to "A spreadsheet goes stale and checks nothing.",
                    2 to "Forcing every API through one gateway is a large migration and still leaves no design governance.",
                    3 to "Front Door routes web traffic. It does not catalogue APIs.",
                ),
            ),
            B.q("sa-m3-50", "sa-app-architecture", "A new version of a container app must receive 10 percent of traffic first, then all of it, with instant rollback. What do you use in Azure Container Apps?", listOf("Multiple revisions with traffic splitting between them", "Deployment slots", "A second Container Apps environment", "Delete the old version, then deploy the new one"), setOf(0), "In multiple revision mode, each deployment creates a revision, and you split traffic between revisions by percentage. Moving traffic back to the old revision is an instant rollback.",
                scenario = "Swiftlane's Android parcel-tracking app calls an API in Container Apps. A bad release last month broke tracking for everyone at once.",
                whyWrong = mapOf(
                    1 to "Deployment slots are an App Service feature.",
                    2 to "A second environment doubles the setup and still needs something to split traffic.",
                    3 to "Deleting the old version first gives no gradual rollout and no rollback.",
                ),
            ),
            B.q("sa-m3-51", "sa-app-architecture", "The web tier is scaling out to many instances, and users lose their shopping basket when a request lands on a different instance. What do you recommend?", listOf("Store session state in Azure Managed Redis", "Turn on session affinity and keep state in memory", "Store session state on each instance's local disk", "Use a single large instance"), setOf(0), "Keeping session state in a shared cache such as Azure Managed Redis means any instance can serve any request. The web tier becomes stateless and can scale out freely.",
                scenario = "Hedgerow Home's website and Android app share a basket service on App Service that keeps baskets in memory. Customers complain that items vanish during busy evenings.",
                whyWrong = mapOf(
                    1 to "Affinity ties users to an instance, so baskets are lost when that instance restarts or scales in.",
                    2 to "Local disks are separate per instance, which is the same problem.",
                    3 to "One instance cannot scale and is a single point of failure.",
                ),
            ),
            // Infrastructure: migrations
            B.q("sa-m3-52", "sa-migrations", "Twenty ASP.NET web apps on IIS servers should move to a managed web platform with minimal code changes. What do you recommend?", listOf("Assess them with Azure Migrate, then migrate them to Azure App Service", "Rehost the IIS servers as Azure VMs and keep patching them", "Rewrite them as Azure Functions", "Move them to Azure Batch"), setOf(0), "Azure Migrate can discover web apps on IIS, check whether they are ready for App Service, and migrate them. This replatforming drops the servers to patch with little or no code change.",
                scenario = "Brookvale Council runs 20 small ASP.NET sites, including the admin site for its Android parking app, on old IIS servers. It wants to stop patching servers.",
                whyWrong = mapOf(
                    1 to "VMs keep the patching work the council wants to drop.",
                    2 to "Rewriting 20 sites as functions is a big code change.",
                    3 to "Batch runs compute jobs, not web apps.",
                ),
            ),
            B.q("sa-m3-53", "sa-migrations", "The board wants to compare the cost of staying on-premises with moving to Azure over five years, based on the servers actually discovered. What do you use?", listOf("The Azure Migrate business case", "Azure Cost Management on the current subscription", "Azure Advisor", "A Service Health report"), setOf(0), "An Azure Migrate business case uses discovered servers, databases and their usage to compare the total cost of ownership on-premises and in Azure over time, with savings and a payback estimate.",
                scenario = "Oxley Group's data centre lease ends in two years. Before any migration, including the back end of its Android loyalty app, the board wants a cost comparison it can trust.",
                whyWrong = mapOf(
                    1 to "Cost Management reports spending on Azure resources that already exist.",
                    2 to "Advisor optimises Azure resources, not on-premises servers.",
                    3 to "Service Health reports Azure incidents, not costs.",
                ),
            ),
            B.q("sa-m3-54", "sa-migrations", "Twelve terabytes of images in Amazon S3 must be copied to Azure Blob Storage, server to server, without downloading them to a local machine first. What do you recommend?", listOf("AzCopy copying from the S3 bucket straight to Blob Storage", "AzCopy on an office PC, downloading the bucket and then uploading it", "Azure Data Box, loaded with the images and shipped to Azure", "Azure File Sync, with the S3 bucket added as a server endpoint"), setOf(0), "AzCopy can copy objects from Amazon S3 directly into Azure Blob Storage. The data moves between the services, not through the machine running the command.",
                scenario = "Vellum Photo is moving its Android photo-printing app from AWS to Azure. All customer images live in an S3 bucket, and the office internet is slow.",
                whyWrong = mapOf(
                    1 to "Downloading 12 TB through the slow office link and uploading it again would take weeks, and it is the local copy the question rules out.",
                    2 to "Data Box is loaded from storage in your own building. The images are in another cloud, so they would first have to be downloaded.",
                    3 to "File Sync server endpoints are folders on Windows Server, not S3 buckets.",
                ),
            ),
            B.q("sa-m3-55", "sa-migrations", "A SQL Server database must move to SQL Managed Instance by restoring the company's existing full and log backups from Blob Storage, keeping it in sync until cutover. What do you use?", listOf("Log Replay Service", "BACPAC import", "Transactional replication to Azure SQL Database", "Azure Data Box"), setOf(0), "Log Replay Service restores SQL Server full, differential and log backups from Blob Storage onto Managed Instance, applying new log backups as they arrive. At cutover the last log is applied and the database comes online.",
                scenario = "Kinloch Insurance already copies its SQL Server backups to Blob Storage. The DBAs want to use them to move the database behind its Android claims app to Managed Instance.",
                whyWrong = mapOf(
                    1 to "BACPAC imports are offline and slow for large databases, with no syncing until cutover.",
                    2 to "The target is Managed Instance, not Azure SQL Database.",
                    3 to "Data Box ships data offline. It does not apply log backups.",
                ),
            ),
            // Infrastructure: networks
            B.q("sa-m3-56", "sa-network-connectivity", "Ten spoke VNets must reach on-premises through one VPN gateway in a hub VNet, without a gateway in each spoke. What do you configure? Select two.", listOf("VNet peering between each spoke and the hub", "Allow gateway transit on the hub side and use remote gateways on the spoke side", "A VPN gateway in every spoke", "Public IP addresses on each spoke's VMs"), setOf(0, 1), "In a hub-and-spoke design, spokes are peered with the hub. With gateway transit allowed on the hub's peering and remote gateways used on each spoke's, all spokes share the hub's VPN gateway to reach on-premises.",
                scenario = "Langley Freight's ten application teams, including the Android dispatch team, each own a spoke VNet. Each wants to reach the warehouse systems, and the network team will pay for only one gateway.",
                whyWrong = mapOf(
                    2 to "A gateway per spoke is the cost the network team refuses.",
                    3 to "Public IPs expose VMs and do not connect to on-premises.",
                ),
