            B.q("sa-m3-57", "sa-network-connectivity", "A third-party router appliance in the hub must exchange routes with Azure's virtual networks dynamically, by BGP, instead of hand-written route tables. What do you recommend?", listOf("Azure Route Server", "A user-defined route table in each subnet", "Azure DNS", "A NAT gateway"), setOf(0), "Azure Route Server lets network virtual appliances exchange routes with Azure using BGP (Border Gateway Protocol, how routers tell each other which networks they can reach). Routes learned this way are programmed into the VNets automatically.",
                scenario = "Kettering Logistics runs an SD-WAN appliance in its hub VNet for the branch network that its Android dispatch app depends on. Routes change often, and hand-edited route tables keep breaking.",
                whyWrong = mapOf(
                    1 to "Hand-written route tables are what keeps breaking.",
                    2 to "DNS resolves names, not network routes.",
                    3 to "A NAT gateway handles outbound internet traffic, not route exchange.",
                ),
            ),
            B.q("sa-m3-58", "sa-network-optimize", "Outbound traffic must be checked for known attack signatures, and the firewall must inspect encrypted HTTPS traffic as well. Which service and tier?", listOf("Azure Firewall Premium, with IDPS and TLS inspection turned on", "Azure Firewall Basic, with threat intelligence filtering in alert mode", "A web application firewall on Application Gateway, with the OWASP rules", "Azure Firewall Standard, with threat intelligence set to alert and deny"), setOf(0), "Azure Firewall Premium adds IDPS, an intrusion detection and prevention system that matches traffic against known attack signatures, and TLS inspection, which decrypts and checks HTTPS traffic. Standard and Basic cannot see inside encrypted traffic.",
                scenario = "Ravenswood Bank sends all outbound traffic from the servers behind its Android app through a central firewall. Malware often hides in encrypted connections.",
                whyWrong = mapOf(
                    1 to "Basic offers threat intelligence in alert mode only, and has neither IDPS nor TLS inspection.",
                    2 to "A WAF on Application Gateway inspects inbound HTTP traffic to web apps, not outbound traffic from the servers.",
                    3 to "Standard blocks known malicious addresses and domains, but it has neither IDPS signatures nor TLS inspection.",
                ),
            ),
            B.q("sa-m3-59", "sa-network-optimize", "Public-facing VMs and load balancers must be protected from large network floods, with tuning for the app's traffic, attack reports and access to rapid response experts. What do you recommend?", listOf("Azure DDoS Network Protection on the virtual network", "The basic DDoS protection every Azure resource gets", "A network security group", "Azure Bastion"), setOf(0), "Azure DDoS Network Protection adds adaptive tuning to each protected public IP, attack metrics and reports, and access to the DDoS Rapid Response team. The always-on infrastructure protection does not tune to your app.",
                scenario = "Ironbridge Games was knocked offline by a flood of traffic on the launch day of its Android game. Its next launch is in two months.",
                whyWrong = mapOf(
                    1 to "Basic infrastructure protection is not tuned to your app, with no reports or rapid response.",
                    2 to "An NSG cannot absorb a flood of traffic.",
