                ),
            ),
            B.q("sa-m3-60", "sa-network-optimize", "A UDP game service runs in three regions. Players must connect to one static global IP address that sends them to the closest healthy region, at layer 4. What do you recommend?", listOf("A cross-region Azure Load Balancer in front of regional Standard Load Balancers", "Azure Front Door Premium, with origins in each of the three regions", "Azure Traffic Manager with performance routing to the regional load balancers", "A Standard Load Balancer with a zone-redundant front end in the main region"), setOf(0), "A cross-region load balancer gives one static anycast IP address worldwide. It sends traffic to the nearest healthy regional load balancer, and works at layer 4, so it handles UDP.",
                scenario = "Starquarry's multiplayer Android game uses UDP for real-time play, hosted in three regions. Players complain about long connect times after a region outage.",
                whyWrong = mapOf(
